declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableEnabledVO;

trait TemplateVariableEnabledAttributeHolder
{
  protected TemplateVariableEnabledVO|bool|null $enabled = null;
  protected bool $enabledAssigned = false;

  public function getEnabledOrDefault(?TemplateVariableEnabledVO $enabled): ?TemplateVariableEnabledVO
  {
    return $this->enabledAssigned ? ($this->enabled !== null ? TemplateVariableEnabledVO::from($this->enabled) : null) : $enabled;
  }
  public function enabled(TemplateVariableEnabledVO|bool|null $enabled): static
  {
    $this->enabled = $enabled;
    $this->enabledAssigned = true;
    return $this;
  }
  public function isEnabled(): ?bool
  {
    return $this->enabled instanceof TemplateVariableEnabledVO ? $this->enabled->value() : $this->enabled;
  }
  public function isEnabledAssigned(): bool
  {
    return $this->enabledAssigned;
  }
  public function writeEnabledTo(mixed $att): void
  {
    if ($this->enabledAssigned) {
      $att->enabled($this->enabled);
    }  }
  public function readEnabledFrom(mixed $att): void
  {
    if ($att->isEnabledAssigned() ) {
      $enabled = $att->isEnabled();
      $this->enabled($enabled);
    }
  }
  public function unsetEnabled(): static
  {
    $this->enabledAssigned = false;
    return $this;
  }
  protected function withDefaultEnabled(): void   
  {
    if ( $this->enabled === null ) {
      $this->enabled = true;
    }
  }
  protected function withAssertedEnabledRules(self $value, ConstraintFailList $errorsList): void  
  {
    if ($value->enabledAssigned = $this->enabledAssigned) {
      $value->enabled = TemplateVariableEnabledVO::tryFrom($this->enabled, $errorsList);
    }
  }
}
